code_sketch:
ZIO.scoped {
  for {
    tx <- transactionalProducer.createTransaction
    _  <- tx.produceChunkBatch(records, Serde.int, Serde.string, OffsetBatch(offsets))
  } yield ()
}.uninterruptible          // the scope closing is the commit; interruption would abort it

